// Ethernet_AVB_TSN_apb checker (generated by scripts/apb/gen_apb.py; do not edit).
// Register model held as an array of words, updated from the APB pins and
// the core's outputs; it predicts PRDATA on every read, PSLVERR, PREADY, irq
// and every core input the wrapper drives. FC: every word read and written,
// every interrupt bit set / cleared / masked / raising irq, stream events,
// strobes, unmapped and misaligned accesses, back-to-back transfers.
`include "cov_macros.svh"
module Ethernet_AVB_TSN_apb_sva (
  input logic PCLK, PRESETN, PSEL, PENABLE, PWRITE,
  input logic [11:0] PADDR,
  input logic [31:0] PWDATA,
  input logic [3:0] PSTRB,
  input logic [31:0] PRDATA,
  input logic PREADY, PSLVERR, irq,
  input logic [7:0] c_cfg_inc_ns,
  input logic [15:0] c_cfg_inc_frac,
  input logic  c_gcl_en,
  input logic [2:0] c_gcl_last,
  input logic [3:0] c_cbs_en,
  input logic [23:0] c_gcl_cycle,
  input logic [63:0] c_gcl_base,
  input logic [35:0] c_cbs_idle,
  input logic [23:0] c_gcl_wivl,
  input logic [3:0] c_gcl_wgates,
  input logic [2:0] c_gcl_waddr,
  input logic [63:0] c_time_set_ns,
  input logic [31:0] c_time_adj_ns,
  input logic [63:0] c_time_ns,
  input logic  c_gcl_running,
  input logic [2:0] c_gcl_entry,
  input logic [3:0] c_gate_state,
  input logic  c_tx_busy,
  input logic [79:0] c_cbs_credit,
  input logic  c_gcl_we,
  input logic  c_time_set,
  input logic  c_time_adj,
  input logic  c_cycle_start,
  input logic  c_tx_start
);
  `COV_CLOCKING(PCLK, !PRESETN)
  wire        m_wr  = PSEL && PENABLE && PWRITE;
  wire        m_rd  = PSEL && PENABLE && !PWRITE;
  wire        m_map = PADDR[1:0] == 2'b00 && (PADDR >> 2) < 21;
  wire [9:0] m_idx = PADDR[11:2];
  wire [31:0] m_be  = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [31:0] m_w [0:20];          // model of every stored word
  logic [1:0] m_set;                // interrupt bits set this clock
  logic m_state_GCL_WR;          // full / valid pulse / available
  logic m_state_TIME_SET;          // full / valid pulse / available
  logic m_state_TIME_ADJ;          // full / valid pulse / available

  always_comb begin
    m_set = '0;
    if (c_cycle_start) m_set[0] = 1'b1;
    if (c_tx_start) m_set[1] = 1'b1;
  end

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      m_w[0] <= 32'h0;
      m_w[1] <= 32'h0;
      m_w[2] <= 32'h0;
      m_w[3] <= 32'h0;
      m_w[4] <= 32'h0;
      m_w[5] <= 32'h8;
      m_w[6] <= 32'hF4240;
      m_w[7] <= 32'h0;
      m_w[8] <= 32'h0;
      m_w[9] <= 32'h0;
      m_w[10] <= 32'h0;
      m_w[11] <= 32'h0;
      m_w[12] <= 32'h0;
      m_w[13] <= 32'h0;
      m_w[14] <= 32'h0;
      m_w[15] <= 32'h0;
      m_w[16] <= 32'h0;
      m_w[17] <= 32'h0;
      m_w[18] <= 32'h0;
      m_w[19] <= 32'h0;
      m_w[20] <= 32'h0;
      m_state_GCL_WR <= 0;
      m_state_TIME_SET <= 0;
      m_state_TIME_ADJ <= 0;
    end else begin
      m_w[1] <= (m_w[1] & ~((m_wr && m_map && m_idx == 1) ? PWDATA & m_be : 0)) | 32'(m_set);
      if (m_wr && m_map && m_idx == 2) m_w[2] <= ((m_w[2] & ~m_be) | (PWDATA & m_be)) & 32'h3;
      if (m_wr && m_map && m_idx == 4) m_w[4] <= ((m_w[4] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 5) m_w[5] <= ((m_w[5] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 6) m_w[6] <= ((m_w[6] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFF;
      if (m_wr && m_map && m_idx == 7) m_w[7] <= ((m_w[7] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 8) m_w[8] <= ((m_w[8] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 9) m_w[9] <= ((m_w[9] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 10) m_w[10] <= ((m_w[10] & ~m_be) | (PWDATA & m_be)) & 32'hF;
      if (m_wr && m_map && m_idx == 11) m_w[11] <= ((m_w[11] & ~m_be) | (PWDATA & m_be)) & 32'h7FFFFFFF;
      m_state_GCL_WR <= m_wr && m_map && m_idx == 11;
      if (m_wr && m_map && m_idx == 12) m_w[12] <= ((m_w[12] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 13) m_w[13] <= ((m_w[13] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      m_state_TIME_SET <= m_wr && m_map && m_idx == 13;
      if (m_wr && m_map && m_idx == 14) m_w[14] <= ((m_w[14] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      m_state_TIME_ADJ <= m_wr && m_map && m_idx == 14;
    end
  end

  function automatic logic [31:0] m_read(input logic [9:0] i);
    case (i)
      0: return 32'h54530200;
      1: return m_w[1];
      2: return m_w[2];
      3: return 0;
      4: return m_w[4];
      5: return m_w[5];
      6: return m_w[6];
      7: return m_w[7];
      8: return m_w[8];
      9: return m_w[9];
      10: return m_w[10];
      11: return m_w[11];
      12: return m_w[12];
      13: return m_w[13];
      14: return m_w[14];
      15: return (32'(c_time_ns[31:0]) << 0);
      16: return (32'(c_time_ns[63:32]) << 0);
      17: return (32'(c_gcl_running) << 0) | (32'(c_gcl_entry) << 1) | (32'(c_gate_state) << 4) | (32'(c_tx_busy) << 8);
      18: return (32'(c_cbs_credit[31:0]) << 0);
      19: return (32'(c_cbs_credit[63:32]) << 0);
      20: return (32'(c_cbs_credit[79:64]) << 0);
      default: return 0;
    endcase
  endfunction

  // ---------------- assertions ----------------
  `SVA_INV(a_pready_zero_wait, PREADY == (PSEL && PENABLE))
  `SVA_IMP(a_pslverr_decode, PSEL && PENABLE, PSLVERR == !m_map)
  `SVA_IMP(a_read_data, m_rd && m_map, PRDATA == m_read(m_idx))
  `SVA_IMP(a_unmapped_read_zero, m_rd && !m_map, PRDATA == 0)
  `SVA_IMP(a_prdata_zero_outside_read, !m_rd, PRDATA == 0)
  `SVA_INV(a_irq_pin, irq == |(m_w[1][1:0] & m_w[2][1:0]))
  `SVA_INV(a_core_cfg_inc_ns, c_cfg_inc_ns == m_w[5][7:0])
  `SVA_INV(a_core_cfg_inc_frac, c_cfg_inc_frac == m_w[5][23:8])
  `SVA_INV(a_core_gcl_en, c_gcl_en == m_w[5][24:24])
  `SVA_INV(a_core_gcl_last, c_gcl_last == m_w[5][27:25])
  `SVA_INV(a_core_cbs_en, c_cbs_en == m_w[5][31:28])
  `SVA_INV(a_core_gcl_cycle, c_gcl_cycle == m_w[6][23:0])
  `SVA_INV(a_core_gcl_base_31_0, c_gcl_base[31:0] == m_w[7][31:0])
  `SVA_INV(a_core_gcl_base_63_32, c_gcl_base[63:32] == m_w[8][31:0])
  `SVA_INV(a_core_cbs_idle_31_0, c_cbs_idle[31:0] == m_w[9][31:0])
  `SVA_INV(a_core_cbs_idle_35_32, c_cbs_idle[35:32] == m_w[10][3:0])
  `SVA_INV(a_core_gcl_wivl, c_gcl_wivl == m_w[11][23:0])
  `SVA_INV(a_core_gcl_wgates, c_gcl_wgates == m_w[11][27:24])
  `SVA_INV(a_core_gcl_waddr, c_gcl_waddr == m_w[11][30:28])
  `SVA_INV(a_core_time_set_ns_31_0, c_time_set_ns[31:0] == m_w[12][31:0])
  `SVA_INV(a_core_time_set_ns_63_32, c_time_set_ns[63:32] == m_w[13][31:0])
  `SVA_INV(a_core_time_adj_ns, c_time_adj_ns == m_w[14][31:0])
  `SVA_INV(a_core_gcl_we, c_gcl_we == m_state_GCL_WR)
  `SVA_INV(a_core_time_set, c_time_set == m_state_TIME_SET)
  `SVA_INV(a_core_time_adj, c_time_adj == m_state_TIME_ADJ)
  `SVA_RST(a_reset_values, !PRESETN, PRDATA == 0 && !irq && c_cfg_inc_ns == 8'h8 && c_cfg_inc_frac == 16'h0 && c_gcl_en == 1'h0 && c_gcl_last == 3'h0 && c_cbs_en == 4'h0 && c_gcl_cycle == 24'hF4240 && c_gcl_base[31:0] == 32'h0 && c_gcl_base[63:32] == 32'h0 && c_cbs_idle[31:0] == 32'h0 && c_cbs_idle[35:32] == 4'h0 && c_gcl_wivl == 24'h0 && c_gcl_wgates == 4'h0 && c_gcl_waddr == 3'h0 && c_time_set_ns[31:0] == 32'h0 && c_time_set_ns[63:32] == 32'h0 && c_time_adj_ns == 32'h0 && !c_gcl_we && !c_time_set && !c_time_adj)

  // ---------------- functional coverage ----------------
  `FC(rd_ID, m_rd && m_map && m_idx == 0)
  `FC(wr_ID, m_wr && m_map && m_idx == 0)
  `FC(rd_IRQ_STATUS, m_rd && m_map && m_idx == 1)
  `FC(wr_IRQ_STATUS, m_wr && m_map && m_idx == 1)
  `FC(rd_IRQ_ENABLE, m_rd && m_map && m_idx == 2)
  `FC(wr_IRQ_ENABLE, m_wr && m_map && m_idx == 2)
  `FC(rd_FLAGS, m_rd && m_map && m_idx == 3)
  `FC(wr_FLAGS, m_wr && m_map && m_idx == 3)
  `FC(rd_SCRATCH, m_rd && m_map && m_idx == 4)
  `FC(wr_SCRATCH, m_wr && m_map && m_idx == 4)
  `FC(rd_CFG0, m_rd && m_map && m_idx == 5)
  `FC(wr_CFG0, m_wr && m_map && m_idx == 5)
  `FC(rd_CFG1, m_rd && m_map && m_idx == 6)
  `FC(wr_CFG1, m_wr && m_map && m_idx == 6)
  `FC(rd_GCL_BASE0, m_rd && m_map && m_idx == 7)
  `FC(wr_GCL_BASE0, m_wr && m_map && m_idx == 7)
  `FC(rd_GCL_BASE1, m_rd && m_map && m_idx == 8)
  `FC(wr_GCL_BASE1, m_wr && m_map && m_idx == 8)
  `FC(rd_CBS_IDLE0, m_rd && m_map && m_idx == 9)
  `FC(wr_CBS_IDLE0, m_wr && m_map && m_idx == 9)
  `FC(rd_CBS_IDLE1, m_rd && m_map && m_idx == 10)
  `FC(wr_CBS_IDLE1, m_wr && m_map && m_idx == 10)
  `FC(rd_GCL_WR, m_rd && m_map && m_idx == 11)
  `FC(wr_GCL_WR, m_wr && m_map && m_idx == 11)
  `FC(rd_TIME_SET0, m_rd && m_map && m_idx == 12)
  `FC(wr_TIME_SET0, m_wr && m_map && m_idx == 12)
  `FC(rd_TIME_SET1, m_rd && m_map && m_idx == 13)
  `FC(wr_TIME_SET1, m_wr && m_map && m_idx == 13)
  `FC(rd_TIME_ADJ, m_rd && m_map && m_idx == 14)
  `FC(wr_TIME_ADJ, m_wr && m_map && m_idx == 14)
  `FC(rd_TIME0, m_rd && m_map && m_idx == 15)
  `FC(wr_TIME0, m_wr && m_map && m_idx == 15)
  `FC(rd_TIME1, m_rd && m_map && m_idx == 16)
  `FC(wr_TIME1, m_wr && m_map && m_idx == 16)
  `FC(rd_STATUS, m_rd && m_map && m_idx == 17)
  `FC(wr_STATUS, m_wr && m_map && m_idx == 17)
  `FC(rd_CREDIT0, m_rd && m_map && m_idx == 18)
  `FC(wr_CREDIT0, m_wr && m_map && m_idx == 18)
  `FC(rd_CREDIT1, m_rd && m_map && m_idx == 19)
  `FC(wr_CREDIT1, m_wr && m_map && m_idx == 19)
  `FC(rd_CREDIT2, m_rd && m_map && m_idx == 20)
  `FC(wr_CREDIT2, m_wr && m_map && m_idx == 20)
  `FC(unmapped_read, m_rd && !m_map && PADDR[1:0] == 0)
  `FC(unmapped_write, m_wr && !m_map && PADDR[1:0] == 0)
  `FC(misaligned_read, m_rd && PADDR[1:0] != 0)
  `FC(misaligned_write, m_wr && PADDR[1:0] != 0)
  `FC(partial_strobe_write, m_wr && m_map && PSTRB != 4'h0 && PSTRB != 4'hF)
  `FC(zero_strobe_write, m_wr && m_map && PSTRB == 4'h0)
  `FC(back_to_back, PSEL && PENABLE ##1 PSEL && !PENABLE)
  `FC(idle_between, PSEL && PENABLE ##1 !PSEL)
  `FC(irq_CYCLE_set, m_set[0])
  `FC(irq_CYCLE_cleared, m_w[1][0] && m_wr && m_map && m_idx == 1 && PWDATA[0] && PSTRB[0])
  `FC(irq_CYCLE_masked, m_w[1][0] && !m_w[2][0])
  `FC(irq_CYCLE_drives_pin, m_w[1][0] && m_w[2][0] && irq)
  `FC(irq_TX_set, m_set[1])
  `FC(irq_TX_cleared, m_w[1][1] && m_wr && m_map && m_idx == 1 && PWDATA[1] && PSTRB[0])
  `FC(irq_TX_masked, m_w[1][1] && !m_w[2][1])
  `FC(irq_TX_drives_pin, m_w[1][1] && m_w[2][1] && irq)
  `FC(GCL_WR_commit, m_state_GCL_WR)
  `FC(TIME_SET_commit, m_state_TIME_SET)
  `FC(TIME_ADJ_commit, m_state_TIME_ADJ)
  `FC_RST(reset_with_pending_irq, PRESETN && m_w[1] != 0 ##1 !PRESETN)
endmodule

bind Ethernet_AVB_TSN_apb Ethernet_AVB_TSN_apb_sva u_apb_sva (.*);
